--duration-slow: 280ms;
--ease-out: cubic-bezier(0.34, 1.61, 0.7, 1);
}
:root {
  /* Primary - Elastic Sky (dark-tuned: 스카이 hue 유지, 다크 캔버스에서 시인성 확보) */
  --color-primary-50:  #07273D;
  --color-primary-100: #0A3656;
  --color-primary-200: #0E4D7A;
  --color-primary-300: #1670AC;
  --color-primary-400: #2491DA;
  --color-primary-500: #3DACF2;   /* Elastic Sky (dark) */
  --color-primary-600: #5BB6F1;
  --color-primary-700: #8ACAF5;
  --color-primary-800: #B8DFF9;
  --color-primary-900: #E6F4FD;

  /* ELK 4색 (시각화 시그니처 — 다크 배경에서 밝게 조정) */
  --color-elk-blue:  #3DACF2;
  --color-elk-teal:  #2DD4BF;
  --color-elk-pink:  #F990C0;
  --color-elk-yellow:#FEC514;

  /* Neutral - EUI grays (inverted ramp — 0 = darkest canvas, 1000 = lightest text) */
  --color-neutral-0:    #0E0F12;
  --color-neutral-50:   #16181D;
  --color-neutral-100:  #1A1C21;     /* page bg */
  --color-neutral-200:  #343741;     /* border */
  --color-neutral-300:  #4B505B;
  --color-neutral-500:  #8A92A0;
  --color-neutral-700:  #B8BFCD;
  --color-neutral-800:  #CDD3DE;
  --color-neutral-900:  #DFE5EF;
  --color-neutral-1000: #F5F7FB;

  /* Semantic (dark-tinted bg + bright legible fg) */
  --color-success-bg: #0C2E28;
  --color-success-fg: #2DD4BF;
  --color-warning-bg: #322405;
  --color-warning-fg: #FEC514;
  --color-error-bg:   #3A1513;
  --color-error-fg:   #F86A60;
  --color-info-bg:    #10324C;
  --color-info-fg:    #5BB6F1;

  /* Surface */
  --bg-base:     #1A1C21;
